\title[The Wrong Polynomial]{The Wrong Polynomial: Affine Fixed-Point Moments,\\ Root-Count Alphabets, and an Accidental $x^5-2$ Measurement}
\author{Aristotle}
\date{September 26, 2026}

\begin{document}

\begin{abstract}
An experiment meant to check ``universal'' root-count statistics for the cubic $x^3-2$, whose Galois group is $S_3$, was in fact run on the quintic $x^5-2$, whose Galois group is the Frobenius group $F_{20}$ of order $20$. The measured mean and mean-square root counts matched the $S_3$ predictions, and the substitution went unnoticed. We explain this exactly. Both groups are members of the affine family $\AGL(1,q)=\{x\mapsto ax+b: a\neq0\}$ acting on $\F_q$, with $q=3$ and $q=5$. We prove the \emph{affine moment law}
\[
\sum_{a\neq0,\ b\in\F_q}\fix(x\mapsto ax+b)^k=q^k+q(q-2)\qquad(k\ge1)
\]
for every finite field $\F_q$. Consequently the normalised fixed-point moments of $\AGL(1,q)$ are $1$, $2$ and $q+2$ for $k=1,2,3$. The first two do not depend on $q$, and the third determines $q$. Through the Chebotarev density theorem, a mean-and-variance test therefore cannot tell $x^3-2$ from $x^5-2$, while the third moment separates them ($5$ versus $7$). We also show that $\AGL(1,3)$ is the full symmetric group on $\F_3$ and that $\AGL(1,q)$ is a proper subgroup of $\Sym(\F_q)$ for $q\ge4$. On the single-field side we determine the possible root counts of $x^n=c$: at most $n$, empty or a coset of $\mu_n$ when $c\ne0$, exactly one when $\gcd(n,q-1)=1$, and the \emph{alphabet} $\{0,1,\ell\}$ for prime exponent $\ell$. Summed over all constants $c$, the counts give first moment $q$ and second moment $1+(q-1)\gcd(n,q-1)$. Explicit checks at $p=23$, $31$ and $151$ show a prime where the two polynomials cannot be told apart, a prime where one reading separates them, and a prime where $x^5-2$ has five roots, which certifies the substitution.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The dial table and the $S_3$ test}
A useful way to probe a Galois group $G$ acting on the $n$ roots of an irreducible integer polynomial $f$ is to count, for many primes $p$, the number $N_f(p)$ of roots of $f$ modulo $p$. For all but finitely many $p$, $N_f(p)$ equals the number of fixed points of a Frobenius element $\mathrm{Frob}_p\in G$. By the Chebotarev density theorem the Frobenius elements are equidistributed over conjugacy classes, with each class weighted by its size. Statistics of $N_f(p)$ over primes therefore converge to statistics of the fixed-point function on $G$.

In an ongoing programme of experiments, groups paired with primes (``dials'') were compared through such statistics. The dials included a cyclic group $C_5$, the Frobenius group $F_{20}$, two dials for $S_3$ at the primes $31$ and $23$, a dihedral group $D_4$ and an alternating group $A_4$. One experiment was meant to test whether the first two root-count moments of the $S_3$ polynomial $x^3-2$ are ``universal''. The polynomial actually fed into the measurement was $x^5-2$. The reported moments agreed with the $S_3$ predictions.

\subsection{Questions and answers}
\begin{enumerate}
\item \emph{Why was the substitution invisible?} Both Galois groups belong to the affine family $\AGL(1,q)$, and the first two normalised fixed-point moments equal $1$ and $2$ for every member of the family (Theorem~\ref{thm:law}, Corollary~\ref{cor:universal}). This is a consequence of double transitivity and has nothing to do with $S_3$ in particular (Proposition~\ref{prop:orbits}).
\item \emph{What detects it?} The third normalised moment equals $q+2$ and so determines $q$ (Theorem~\ref{thm:third}). Also, the top letter of the root-count alphabet $\{0,1,\ell\}$ gives a certificate at a single prime (Theorem~\ref{thm:alphabet}, Section~\ref{sec:dials}).
\item \emph{Is $S_3$ just a small $F_{20}$?} No. $\AGL(1,3)=\Sym(\F_3)\cong S_3$, but $\AGL(1,q)$ is a proper subgroup of $\Sym(\F_q)$ for every $q\ge4$ (Theorem~\ref{thm:sym}).
\end{enumerate}
The verdict is that the accidental measurement was \emph{true but misattributed}. It correctly measured the first two moments of $F_{20}$, and those numbers cannot tell the members of a doubly transitive family apart.

\section{Preliminaries}
Throughout, $\F$ is a finite field with $q=|\F|\ge2$ elements.

\begin{definition}[Affine group]
For $a\in\F^\times$ and $b\in\F$, the affine map $\alpha_{a,b}:\F\to\F$ is $\alpha_{a,b}(x)=ax+b$. It is a bijection with inverse $y\mapsto a^{-1}(y-b)$. The set $\AGL(1,q)=\{\alpha_{a,b}\}$ is a group under composition.
\end{definition}

\begin{lemma}[Faithfulness]\label{lem:faithful}
The map $(a,b)\mapsto\alpha_{a,b}$ from $\F^\times\times\F$ to $\Sym(\F)$ is injective. In particular $|\AGL(1,q)|=q(q-1)$.
\end{lemma}
\begin{proof}
If $\alpha_{a,b}=\alpha_{a',b'}$, evaluating at $0$ gives $b=b'$, and then evaluating at $1$ gives $a=a'$.
\end{proof}

\begin{definition}[Fixed points and moments]
Let $\Fix(a,b)=\{x\in\F:ax+b=x\}$ and $\fix(a,b)=|\Fix(a,b)|$. For $k\ge1$ put
\[
S_k(q)=\sum_{a\in\F^\times}\sum_{b\in\F}\fix(a,b)^k,\qquad M_k(q)=\frac{S_k(q)}{q(q-1)}.
\]
\end{definition}

\begin{definition}[Root sets]
For $n\ge0$ and $c\in\F$ put $R_n(c)=\{x\in\F:x^n=c\}$ and $r_n(c)=|R_n(c)|$, and write $\mu_n(\F)=R_n(1)$.
\end{definition}

\begin{background}[Galois groups of radical polynomials]\label{bg:galois}
Let $\ell$ be an odd prime and let $a$ be an integer that is not an $\ell$-th power. The roots of $x^\ell-a$ are $\theta\zeta^i$ with $i\in\mathbb{Z}/\ell$, where $\theta^\ell=a$ and $\zeta$ is a primitive $\ell$-th root of unity. Every automorphism sends $\zeta\mapsto\zeta^u$ and $\theta\mapsto\theta\zeta^v$, so it acts on indices by $i\mapsto ui+v$, and the Galois group is $\AGL(1,\ell)$ acting on $\F_\ell$. So $\mathrm{Gal}(x^3-2)\cong\AGL(1,3)$ and $\mathrm{Gal}(x^5-2)\cong\AGL(1,5)=F_{20}$.
\end{background}

\begin{background}[Chebotarev transfer]\label{bg:cheb}
If $G$ is the Galois group of an irreducible $f\in\mathbb{Z}[x]$, then for every $k$,
\[
\lim_{X\to\infty}\frac{1}{\pi(X)}\sum_{p\le X}N_f(p)^k=\frac{1}{|G|}\sum_{g\in G}\fix(g)^k .
\]
\end{background}

\section{The affine moment law}

\begin{lemma}[Fixed points of an affine map]\label{lem:fix}
For $a,b\in\F$,
\[
\fix(a,b)=\begin{cases}q & a=1,\ b=0,\\ 0 & a=1,\ b\neq0,\\ 1 & a\ne1.\end{cases}
\]
\end{lemma}
\begin{proof}
If $a=1$ and $b=0$, every point is fixed. If $a=1$ and $b\ne0$, then $x+b=x$ is impossible. If $a\ne1$, then $1-a$ is invertible and $ax+b=x\iff x=b/(1-a)$.
\end{proof}

\begin{lemma}[Contribution of one slope]\label{lem:slope}
For every $a\in\F$ and $k\ge1$, $\sum_{b}\fix(a,b)^k$ equals $q^k$ if $a=1$ and $q$ if $a\neq1$.
\end{lemma}
\begin{proof}
For $a=1$ only $b=0$ contributes, since $0^k=0$. For $a\ne1$ each of the $q$ terms is $1$.
\end{proof}

\begin{theorem}[Affine moment law]\label{thm:law}
For every finite field with $q$ elements and every $k\ge1$,
\[
S_k(q)=q^k+q(q-2).
\]
\end{theorem}
\begin{proof}
Split off the slope $a=1\in\F^\times$, which contributes $q^k$. Each of the remaining $q-2$ nonzero slopes contributes $q$.
\end{proof}

\begin{corollary}[The first three moments]\label{cor:three}
$S_1(q)=q(q-1)$, $S_2(q)=2q(q-1)$ and $S_3(q)=(q+2)q(q-1)$. Equivalently $M_1=1$, $M_2=2$ and $M_3=q+2$.
\end{corollary}
\begin{proof}
Direct expansion: $q+q(q-2)=q(q-1)$, then $q^2+q(q-2)=2q(q-1)$, and $q^3+q^2-2q=q(q-1)(q+2)$.
\end{proof}

More generally $M_k(q)=(q^{k-1}+q-2)/(q-1)$. For example $M_4(q)=q^2+q+2$, which is $14$ for $S_3$ and $32$ for $F_{20}$.

\begin{corollary}[Universality of the low moments]\label{cor:universal}
For any finite fields $\F$ and $\K$, $M_1(|\F|)=M_1(|\K|)$ and $M_2(|\F|)=M_2(|\K|)$.
\end{corollary}

\begin{theorem}[The third moment determines the field size]\label{thm:third}
If $M_3(|\F|)=M_3(|\K|)$, then $|\F|=|\K|$.
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:three} the hypothesis reads $|\F|+2=|\K|+2$.
\end{proof}

\begin{example}[$S_3$ versus $F_{20}$]
For $q=3$: $S_1=6$, $S_2=12$, $S_3=30=6\cdot5$. For $q=5$: $S_1=20$, $S_2=40$, $S_3=140=20\cdot7$. The normalised moments are $(1,2,5)$ and $(1,2,7)$.
\end{example}

\section{The affine group versus the symmetric group}

\begin{theorem}\label{thm:sym}
\begin{enumerate}
\item The map $\F_3^\times\times\F_3\to\Sym(\F_3)$, $(a,b)\mapsto(x\mapsto ax+b)$, is a bijection, so $\AGL(1,3)=\Sym(\F_3)\cong S_3$.
\item If $q\ge4$, the map $\F^\times\times\F\to\Sym(\F)$, $(a,b)\mapsto(x\mapsto ax+b)$, is not surjective. In particular $F_{20}\ne S_5$.
\end{enumerate}
\end{theorem}
\begin{proof}
The map is injective by Lemma~\ref{lem:faithful}. (1) Both sides have $6=3!$ elements. (2) Surjectivity would give $q!\le q(q-1)$. But $q!=q(q-1)(q-2)!$ with $(q-2)!\ge2$, so $q!\ge 2q(q-1)>q(q-1)$.
\end{proof}

\section{Root counts of $x^n=c$ in a finite field}

\begin{proposition}[Degree bound]\label{prop:bound}
For $n\ge1$, $r_n(c)\le n$.
\end{proposition}
\begin{proof}
$x^n-c$ is a nonzero polynomial of degree $n$ over a field, so it has at most $n$ roots.
\end{proof}

\begin{proposition}[Coset dichotomy]\label{prop:coset}
Let $n\ge1$ and $c\ne0$. Then $r_n(c)\in\{0,|\mu_n(\F)|\}$.
\end{proposition}
\begin{proof}
If $x_0\in R_n(c)$, then $x_0\ne0$, and $z\mapsto x_0z$ and $y\mapsto y/x_0$ are inverse bijections between $\mu_n(\F)$ and $R_n(c)$.
\end{proof}

\begin{proposition}[Inert exponents]\label{prop:inert}
If $n\ge1$ and $\gcd(n,q-1)=1$, then $x\mapsto x^n$ is a bijection of $\F$ and $r_n(c)=1$ for all $c$.
\end{proposition}
\begin{proof}
Suppose $x^n=y^n$ with $y\ne0$. Then $x\neq0$ as well, and $u=x/y$ satisfies $u^n=u^{q-1}=1$, so $u^{\gcd(n,q-1)}=u=1$. If $y=0$ then $x=0$. So the map is injective, and hence bijective because $\F$ is finite.
\end{proof}

\begin{theorem}[Root-count alphabet]\label{thm:alphabet}
Let $\ell$ be prime and $c\in\F^\times$. Then $r_\ell(c)\in\{0,1,\ell\}$. More precisely, $r_\ell(c)=1$ if $\ell\nmid q-1$, and $r_\ell(c)\in\{0,\ell\}$ if $\ell\mid q-1$.
\end{theorem}
\begin{proof}
If $\ell\nmid q-1$, apply Proposition~\ref{prop:inert}. If $\ell\mid q-1=|\F^\times|$, Cauchy's theorem gives an element of order $\ell$. It is a primitive $\ell$-th root of unity, so $|\mu_\ell(\F)|=\ell$. Now apply Proposition~\ref{prop:coset}.
\end{proof}

\begin{corollary}[Inert primes]
If $p\not\equiv1\pmod5$, then $x^5-2$ has exactly one root modulo $p$. If $p\equiv2\pmod3$, then $x^3-2$ has exactly one root modulo $p$.
\end{corollary}

\begin{theorem}[Universal mean over constants]\label{thm:mean}
For every $n\ge0$, $\sum_{c\in\F}r_n(c)=q$. For $n\ge1$, also $\sum_{c\ne0}r_n(c)=q-1$.
\end{theorem}
\begin{proof}
The sets $R_n(c)$ are the fibres of $x\mapsto x^n$. For $n\ge1$, $R_n(0)=\{0\}$.
\end{proof}

\begin{theorem}[Second moment over constants]\label{thm:second}
For $n\ge1$, $\displaystyle\sum_{c\in\F}r_n(c)^2=1+(q-1)|\mu_n(\F)|=1+(q-1)\gcd(n,q-1)$.
\end{theorem}
\begin{proof}
$\sum_c r_n(c)^2=\sum_{x\in\F}r_n(x^n)$. The term $x=0$ contributes $1$. For $x\ne0$, the set $R_n(x^n)$ contains $x$, so by Proposition~\ref{prop:coset} it has $|\mu_n(\F)|$ elements. Cyclicity of $\F^\times$ gives $|\mu_n(\F)|=\gcd(n,q-1)$.
\end{proof}

\begin{remark}
Averaged over constants in a fixed field, the mean is universal but the second moment depends on $n$: in $\F_{31}$ it is $91$ for $n=3$ and $151$ for $n=5$. Averaged over primes for a fixed polynomial, the second moment is $2$ for both polynomials. Whether a statistic is universal depends on the averaging measure.
\end{remark}

\section{Dial checks at single primes}\label{sec:dials}

\begin{proposition}[Prime $23$]
Modulo $23$, both $x^3-2$ and $x^5-2$ have exactly one root (namely $16$ and $6$).
\end{proposition}
\begin{proof}
$23\equiv2\pmod3$ and $23\not\equiv1\pmod5$.
\end{proof}

\begin{proposition}[Prime $31$]
Modulo $31$, $x^3-2$ has exactly the roots $4,7,20$, and $x^5-2$ has none.
\end{proposition}
\begin{proof}
$4^3\equiv7^3\equiv20^3\equiv2$, and three is the maximum by Proposition~\ref{prop:bound}. If $x^5\equiv2$, then $2^6\equiv x^{30}\equiv1$, but $2^6=64\equiv2\pmod{31}$.
\end{proof}

\begin{proposition}[Prime $151$]\label{prop:151}
Modulo $151$, $x^5-2$ has exactly the five roots $22,25,49,90,116$. Since $x^3-c$ has at most three roots for every $c$, this root count is not the root count of any $x^3-c$.
\end{proposition}

The first primes at which $x^5-2$ has five roots are $151$, $241$ and $251$. By Chebotarev they have density $1/20$.

\section{Interpretation: orbit counting}

\begin{proposition}[Moments count orbits on tuples]\label{prop:orbits}
Let $G$ act on a finite set $X$ with $|X|\ge k$. For $j\ge1$, $\frac1{|G|}\sum_g\fix(g)^j$ is the number of $G$-orbits on $X^j$. If $G$ is $k$-transitive and $j\le k$, this number equals the number of set partitions of $\{1,\dots,j\}$. In particular it is $1$ for $j=1$ and $2$ for $j=2$.
\end{proposition}
\begin{proof}[Proof sketch]
$\fix(g)^j$ counts the fixed points of $g$ on $X^j$, so the first claim is the orbit-counting lemma. The equality pattern of a $j$-tuple is invariant under $G$. When $j\le k$, $k$-transitivity makes tuples with the same pattern lie in one orbit.
\end{proof}

$\AGL(1,q)$ is sharply $2$-transitive, which explains $M_1=1$ and $M_2=2$. On triples there are $1$ all-equal orbit and $3$ orbits with exactly one coincidence. The all-distinct triples $(u,v,w)$ split into $q-2$ orbits, indexed by the invariant $(w-u)/(v-u)\in\F\setminus\{0,1\}$. This gives $M_3=q+2$ orbits, which equals the Bell number $B_3=5$ exactly when $q=3$.

