from fractions import Fraction
from typing import Dict, List


def affine_fixed_points(a: int, b: int, q: int) -> int:
    """Fixed points of x -> a x + b on F_q (q prime): q, 0 or 1."""
    if a % q == 1:
        return q if b % q == 0 else 0
    return 1


def affine_moment_closed_form(q: int, k: int) -> Fraction:
    """Normalised k-th moment M_k(q) = (q^k + q(q-2)) / (q(q-1)), k >= 1."""
    if k < 1 or q < 2:
        raise ValueError("need k >= 1 and q >= 2")
    return Fraction(q ** k + q * (q - 2), q * (q - 1))


def affine_moment_brute_force(q: int, k: int) -> Fraction:
    """Same quantity by enumerating every map and every point (q prime)."""
    total = 0
    for a in range(1, q):
        for b in range(q):
            fix = sum(1 for x in range(q) if (a * x + b - x) % q == 0)
            total += fix ** k
    return Fraction(total, q * (q - 1))


def moment_table(qs: List[int], kmax: int) -> Dict[int, List[Fraction]]:
    table: Dict[int, List[Fraction]] = {}
    for q in qs:
        row = []
        for k in range(1, kmax + 1):
            m = affine_moment_closed_form(q, k)
            assert m == affine_moment_brute_force(q, k)
            row.append(m)
        table[q] = row
    return table


if __name__ == "__main__":
    for q, row in moment_table([2, 3, 5, 7, 11], 4).items():
        print(q, [str(m) for m in row])

from math import gcd
from typing import Tuple


def root_count_power_residue(n: int, c: int, p: int) -> int:
    """#{x in F_p : x^n = c} using the n-th power residue criterion.

    For c != 0 mod p: with g = gcd(n, p-1), the count is g if
    c^((p-1)/g) = 1 (mod p) and 0 otherwise.  If g = 1 it is always 1.
    """
    c %= p
    if c == 0:
        return 1
    g = gcd(n, p - 1)
    if g == 1:
        return 1
    return g if pow(c, (p - 1) // g, p) == 1 else 0


def dial_check(p: int, n_intended: int = 3, n_actual: int = 5, c: int = 2) -> Tuple[int, int, str]:
    """Compare the readings of x^n_intended - c and x^n_actual - c at prime p."""
    r1 = root_count_power_residue(n_intended, c, p)
    r2 = root_count_power_residue(n_actual, c, p)
    if r2 > n_intended:
        verdict = "certificate: the reading exceeds the degree of the intended polynomial"
    elif r1 == r2:
        verdict = "indistinguishable"
    else:
        verdict = "separated"
    return r1, r2, verdict


if __name__ == "__main__":
    for p in (23, 31, 151, 241, 251):
        print(p, dial_check(p))

from math import gcd
from typing import Optional, Tuple


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def root_count(n: int, c: int, p: int) -> int:
    g = gcd(n, p - 1)
    if g == 1:
        return 1
    return g if pow(c % p, (p - 1) // g, p) == 1 else 0


def third_moment_discriminator(n_unknown: int, c: int = 2, start: int = 7,
                               max_primes: int = 5000) -> Tuple[str, int, Optional[int], float]:
    """Decide whether a black-box radical polynomial is x^3 - c (M3 -> 5)
    or x^5 - c (M3 -> 7).

    Streams primes, keeps the running third moment, and stops early at the
    first prime whose root count exceeds 3 (a certificate for the quintic).
    Returns (verdict, primes used, certificate prime or None, running M3).
    """
    s3, used, p = 0, 0, start
    while used < max_primes:
        if is_prime(p):
            r = root_count(n_unknown, c, p)
            used += 1
            s3 += r ** 3
            if r > 3:
                return "quintic (certificate)", used, p, s3 / used
        p += 1
    m3 = s3 / used
    return ("cubic" if abs(m3 - 5) < abs(m3 - 7) else "quintic"), used, None, m3


if __name__ == "__main__":
    print(third_moment_discriminator(5))
    print(third_moment_discriminator(3, max_primes=2000))
